import java.util.Scanner;

public class Main {
    static final int MAXN = 266666;
    static int n, k, M;
    static long[] factorial = new long[MAXN + 1];
    static long[] inv_factorial = new long[MAXN + 1];
    static long[][] dp_table = new long[30][22];
    static long[][] a_matrix = new long[18][1 << 17];
    static long[] b_array = new long[1 << 17];

    static long power(long base, long exp) {
        long result = 1;
        long current = base;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * current) % M;
            }
            current = (current * current) % M;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        M = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(power(k, n));
            sc.close();
            return;
        }

        factorial[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorial[i] = (factorial[i - 1] * i) % M;
        }

        inv_factorial[n] = power(factorial[n], M - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % M;
        }

        int half_n = n >> 1;
        for (int i = 0; i <= half_n; i++) {
            int popcnt = Integer.bitCount(i);
            a_matrix[popcnt][i] = inv_factorial[i * 2];
        }

        for (int i = 0; i < 17; i++) {
            for (int j = 0; j < 17; j++) {
                for (int u = 0; u < (1 << 17); u++) {
                    if (((u >> j) & 1) == 1) {
                        a_matrix[i][u] += a_matrix[i][u ^ (1 << j)];
                    }
                }
            }
        }

        for (int i = 0; i < 17; i++) {
            for (int u = 0; u < (1 << 17); u++) {
                a_matrix[i][u] %= M;
            }
        }

        int popcnt_n = Integer.bitCount(half_n);
        for (int i = 0; i < (1 << 17); i++) {
            for (int j = 0; j <= 17; j++) {
                for (int u = 0; u <= 17; u++) {
                    for (int v = 0; v + u <= 17; v++) {
                        dp_table[j][u + v] += a_matrix[u][i] * (j > 0 ? dp_table[j - 1][v] : 1);
                    }
                    if ((u & 7) == 0) {
                        for (int v = 0; v <= 17; v++) {
                            dp_table[j][v] %= M;
                        }
                    }
                }
                for (int v = 0; v <= 17; v++) {
                    dp_table[j][v] %= M;
                }
            }
            b_array[i] = dp_table[k][popcnt_n];
        }

        for (int i = 0; i < 17; i++) {
            for (int j = 0; j < (1 << 17); j++) {
                if (((j >> i) & 1) == 1) {
                    b_array[j] -= b_array[j ^ (1 << i)];
                }
            }
        }

        long result = ((power(k, n * 2) - b_array[n] * factorial[n * 2]) % M + M) % M;
        System.out.println(result);
        sc.close();
    }
}

